<?php
require __DIR__.'/auth.php'; require_role(['ADMIN','OPERATOR']);
$api=rtrim(getenv('MONITOR_API_URL')?:'http://api:3000','/');
function api_json(string $method,string $path,?array $body=null):array{global $api;$ch=curl_init($api.$path);$o=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>['Accept: application/json','Content-Type: application/json']];if($body!==null)$o[CURLOPT_POSTFIELDS]=json_encode($body);curl_setopt_array($ch,$o);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return ['code'=>$code,'data'=>json_decode($raw?:'{}',true)?:[]];}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';if($a==='rule'){api_json('POST','/api/v1/alert-rules',['name'=>trim($_POST['name']),'metric_key'=>trim($_POST['metric_key']),'operator'=>$_POST['operator'],'threshold'=>(float)$_POST['threshold'],'severity'=>$_POST['severity'],'duration_sec'=>(int)$_POST['duration_sec']]);}elseif($a==='channel'){api_json('POST','/api/v1/notification-channels',['name'=>trim($_POST['channel_name']),'type'=>$_POST['channel_type'],'config'=>json_decode($_POST['channel_config']?:'{}',true)?:[]]);}elseif($a==='test'){ $r=api_json('POST','/api/v1/notification-channels/'.(int)$_POST['id'].'/test',['message'=>'Monitoring test from Admin']);$msg=$r['data']['success']?'Test sent successfully':('Test failed: '.($r['data']['error']??'unknown'));}elseif($a==='delete_rule')api_json('DELETE','/api/v1/alert-rules/'.(int)$_POST['id']);elseif($a==='delete_channel')api_json('DELETE','/api/v1/notification-channels/'.(int)$_POST['id']);header('Location: admin_alerting.php');exit;}
$rules=api_json('GET','/api/v1/alert-rules')['data'];$channels=api_json('GET','/api/v1/notification-channels')['data'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alerting Administration</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="index.php">Monitoring Admin</a><a class="btn btn-outline-light btn-sm" href="admin_infrastructure.php">Infrastructure</a></div></nav><main class="container-fluid p-4"><h2>Alerting Administration</h2><?php if($msg):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?><div class="row g-4"><div class="col-lg-6"><div class="card"><div class="card-header">Create Alert Rule</div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="rule"><input class="form-control mb-2" name="name" placeholder="CPU high" required><input class="form-control mb-2" name="metric_key" placeholder="system.cpu.util" required><div class="row"><div class="col"><select class="form-select" name="operator"><option>&gt;</option><option>&gt;=</option><option>&lt;</option><option>&lt;=</option><option>=</option><option>!=</option></select></div><div class="col"><input class="form-control" name="threshold" type="number" step="0.01" required></div></div><div class="row mt-2"><div class="col"><select class="form-select" name="severity"><option>WARNING</option><option>HIGH</option><option>CRITICAL</option><option>INFO</option></select></div><div class="col"><input class="form-control" name="duration_sec" type="number" min="0" value="0"></div></div><button class="btn btn-primary mt-3">Create rule</button></form></div></div><div class="card mt-3"><div class="card-header">Rules</div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Name</th><th>Key</th><th>Condition</th><th>Severity</th><th></th></tr></thead><tbody><?php foreach($rules as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['metric_key'])?></td><td><?=e($r['operator'].' '.$r['threshold'])?></td><td><?=e($r['severity'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_rule"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header">Notification Channel</div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="channel"><input class="form-control mb-2" name="channel_name" placeholder="Ops Telegram" required><select class="form-select mb-2" name="channel_type"><option>TELEGRAM</option><option>EMAIL</option><option>WEBHOOK</option></select><textarea class="form-control" name="channel_config" rows="5" placeholder='{"botToken":"...","chatId":"..."}'></textarea><button class="btn btn-primary mt-3">Create channel</button></form></div></div><div class="card mt-3"><div class="card-header">Channels</div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Name</th><th>Type</th><th>Enabled</th><th>Test</th><th></th></tr></thead><tbody><?php foreach($channels as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['type'])?></td><td><?=!empty($c['enabled'])?'YES':'NO'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="test"><input type="hidden" name="id" value="<?=e($c['id'])?>"><button class="btn btn-sm btn-outline-primary">Test</button></form></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_channel"><input type="hidden" name="id" value="<?=e($c['id'])?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></main></body></html>